"""QA 240 D repro (generated by tools/qa/qa_d_core.py). Signature: stderr|operators/menu_items.py:459|RuntimeError: Operator bpy#ops#object#mode_set#poll() Cannot edit hidden object

Run: ALLSET_SANDBOX=qa_d python tests/run.py --no-build -k __none__ --extra tools/qa/repro_d_3_491.py
"""
from importlib.util import module_from_spec, spec_from_file_location
from pathlib import Path

_spec = spec_from_file_location('qa_d_core', Path(__file__).resolve().parent / 'qa_d_core.py')
core = module_from_spec(_spec)
_spec.loader.exec_module(core)

ACTIONS = [
 {
  "kind": "ctx",
  "spec": {
   "sel": [
    "pCube1",
    "pCylinder1",
    "pSphere1"
   ],
   "active": "pSphere1",
   "mode": "OBJECT"
  }
 },
 {
  "kind": "key",
  "op": "allset.visibility",
  "props": {
   "action": "HIDE"
  },
  "km": "Object Mode",
  "w": 1
 },
 {
  "kind": "menu",
  "path": "Mesh Tools/Sculpting Tools/Smooth Tool",
  "w": 1
 }
]
SIGNATURE = "stderr|operators/menu_items.py:459|RuntimeError: Operator bpy#ops#object#mode_set#poll() Cannot edit hidden object"


def test_repro():
    mk = core.Monkey()
    mk.run(ACTIONS)
    hits = [f for f in mk.failures if f[1] == SIGNATURE]
    assert not hits, hits[0][2][-1500:]
